"""Snap clock times to a fixed step, such as 15 minutes for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

def _check_step(step_minutes: int) -> None:
    """The step must be positive and divide an hour evenly, such as 5 or 15."""
    if step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(f"step must divide an hour evenly, got {step_minutes}")

def _snap(minutes: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Exact halves round up."""
    return (minutes + step_minutes // 2) // step_minutes * step_minutes

def _snap_span(span: Span, step_minutes: int) -> Span:
    """Round both ends to the step. A span that collapses to nothing is an error."""
    start = _snap(span.start, step_minutes)
    end = _snap(span.end, step_minutes)
    if end <= start:
        raise ValueError(f"{format_span(span)} rounds to nothing at {step_minutes}")
    return Span(start, end)

def _label(span: Span) -> str:
    hours, mins = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {mins}m)"

# ---
def snap_spans(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Label each span with its start and end rounded to the step, in input order."""
    _check_step(step_minutes)
    return [_label(_snap_span(span, step_minutes)) for span in spans]

