import unittest

from hourglass.models import Span
from hourglass.rounding import snap_spans

class SnapTests(unittest.TestCase):
    def test_rounds_start_and_end_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 13)]
        self.assertEqual(snap_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        self.assertEqual(snap_spans([Span(545, 1025)], 10), ["09:10-17:10 (8h 0m)"])

    def test_step_of_one_keeps_minutes(self):
        self.assertEqual(snap_spans([Span(542, 1033)], 1), ["09:02-17:13 (8h 11m)"])

    def test_end_of_day_is_allowed(self):
        self.assertEqual(snap_spans([Span(1430, 1440)], 15), ["23:45-24:00 (0h 15m)"])

    def test_keeps_input_order(self):
        spans = [Span(600, 720), Span(540, 600)]
        self.assertEqual(
            snap_spans(spans, 30), ["10:00-12:00 (2h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(snap_spans([], 15), [])

    def test_bad_step_raises(self):
        for step in (0, -15, 7, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    snap_spans([Span(540, 600)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            snap_spans([Span(541, 545)], 15)
